  origin: "An ancient transverse bamboo flute of Zhou China, closed at both ends, known from the 詩經 Shijing (伯氏吹埙，仲氏吹篪) and from the tomb of Marquis Yi of Zeng 曾侯乙.",
  history: "Paired with the xun as a symbol of brotherly harmony, it survived in court ritual music into the Qing but left everyday use early.",
