  variants: "Qing ritual chi had a blowing hole and six finger holes; Korean ritual music keeps the 지 ji.",
  today: "Kept only in reconstructed Confucian ritual music in China and in Korean court ritual music.",
  hs: "421.121.12",
  relatives: ["dizi","xun","daegeum"],
