  origin: "The Chinese end-blown vertical bamboo flute, named 洞箫 dongxiao, which developed from the Qiang flute 羌笛 of western China in the Han.",
  history: "Distinct from the panpipe also once called xiao, it became a scholar's instrument paired with the guqin; the 尺八 chiba form of the Tang passed to Japan as the shakuhachi.",
