  svg: "<svg viewBox=\"0 0 64 64\" stroke=\"currentColor\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M4 40 L10 30 L58 22 L60 28 L12 46 Z\"/><line x1=\"12\" y1=\"37\" x2=\"56\" y2=\"25\"/><line x1=\"12\" y1=\"41\" x2=\"57\" y2=\"28\"/><path d=\"M20 18 L36 44\"/></svg>",
  origin: "A zither sounded with a stick of resined wood, recorded in Tang China.",
  history: "The rubbing stick was later replaced by a horsehair bow in some forms; it survives in northern Chinese folk music as the 轧琴 and influenced the Korean ajaeng.",
  materials: "A wooden zither body with movable bridges and silk or metal strings; a rosined stick or horsehair bow.",
  usage: "Laid flat; the right hand rubs the strings with the stick while the left presses beyond the bridges.",
