  tuning: "Pentatonic by movable bridges, like the zheng.",
  acoustics: "Rosined wooden stick or bow drawn across the strings → silk strings over movable bridges → a long wooden zither body.",
  making: "A zither body of wood with silk strings and a rubbing stick of peeled forsythia or other wood.",
  role: "Sustained melody in folk ensembles and opera accompaniment.",
  players: "Tang–Song entertainment musicians; later folk musicians of northern China.",
  repertoire: "Shandong and Hebei folk music and local opera accompaniment, where it is called 轧琴.",
