  origin: "Tuned sets of bronze bells from Zhou China, developed from Shang bells; the set from the tomb of Marquis Yi of Zeng 曾侯乙 (433 BCE) has 65 bells.",
  history: "Each almond-shaped bell gives two pitches depending on where it is struck; bianzhong marked aristocratic rank and Zhou ritual music, and later dynasties recast sets for Confucian court rites.",
