  role: "Melody and framing in ritual ensembles.",
  players: "Court ritual musicians.",
  repertoire: "Zhou ritual music; modern reconstructions play arrangements and new compositions.",
  notation: "The Zeng bells bear inscriptions naming pitches and their equivalents in other states' systems.",
  meaning: "A symbol of aristocratic rank and ritual order 礼乐; the number of bells allowed was set by rank.",
  finds: "The 65-bell set from the tomb of Marquis Yi of Zeng 曾侯乙, 433 BCE, at Suizhou, Hubei.",
  variants: "Sets of 甬钟, 钮钟 and 镈 bells, from a few to dozens of bells.",
  today: "Reproductions are played in museums and concerts.",
