  svg: "<svg viewBox=\"0 0 64 64\" stroke=\"currentColor\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"14\" y=\"26\" width=\"40\" height=\"12\" rx=\"2\"/><path d=\"M20 32 L50 32\"/><line x1=\"14\" y1=\"32\" x2=\"6\" y2=\"32\"/><circle cx=\"52\" cy=\"32\" r=\"1\"/></svg>",
  origin: "A jaw harp of bamboo or metal played across China, Siberia and the steppe, by Jurchen and Manchu as well as Yi and other peoples.",
  history: "Jaw harps of bone appear in ancient northern Chinese and Xiongnu sites; the Manchu 'mukūn' and the Yi kouxian keep the tradition alive.",
  materials: "A bamboo slip with a cut tongue, or a metal frame with a steel tongue.",
  usage: "Held to the open lips and plucked or jerked by a string while the mouth shapes overtones.",
  skills: "Changing mouth shape and breath to select overtones; speech-like courting patterns.",
  scenes: "Courting, private song, shamanic rites.",
  partners: ["yaoling","untun","erhu"],
  sound: "A soft, twanging buzz whose overtones the player shapes with the mouth, so a melody of whistling harmonics floats above a steady drone. Bamboo types are quiet and breathy, metal ones brighter and more ringing.",
  range: "A single fundamental drone; the melody uses roughly the 4th–12th harmonics above it.",
  tuning: "Fixed by the tongue's length and weight; Yi and other players use sets of two to five tongues of different pitches.",
  acoustics: "The tongue is plucked (or jerked by a string) and vibrates through a slot; the player's mouth cavity acts as a variable resonator that selects overtones.",
  making: "Bamboo kouxian are carved in one piece by the player or village craftsmen; metal ones are hammered and filed from brass or steel by smiths.",
  role: "Solo melody over its own drone.",
  players: "Young people courting, especially women among the Yi, Lisu and other peoples; also Manchu and other northern peoples.",
  repertoire: "Courting songs and talk-like melodies said to 'speak' words; the Yi solo tradition of Liangshan.",
  meaning: "Used as a private voice between lovers, its melodies can carry words understood only by those who know the tune.",
  finds: "Over twenty bone jaw harps were excavated at 石峁 Shimao in Shaanxi, dated to about 2000 BC, among the oldest known anywhere.",
  variants: "Single- and multi-tongue bamboo or brass forms of the Yi, Lisu, Hani and Naxi; Manchu, Mongol and Siberian metal frame jaw harps.",
  today: "Living in southwestern minority communities and revived in folk-music circles.",
  hs: "121.21 (bamboo, idioglot); 121.22 (metal frame, heteroglot)",
  relatives: ["marranzanu","trompe"],
  techniques: [
    { name: "Mouth resonance", how: "Changing the mouth shape while the reed vibrates picks out overtone melodies.", play: "harmonic" },
    { name: "Plucked drone", how: "The reed is plucked or the string jerked, a buzzing drone.", play: "normal" },
  ],
