  origin: "The thirteen-string koto of 雅楽 gagaku, brought from Tang China in the Nara period.",
  history: "Kept at the Heian court as a gentleman's instrument, it plays fixed arpeggio patterns in gagaku and is the ancestor of the later koto.",
  materials: "A long paulownia body, silk strings, movable bridges and small bamboo picks.",
  usage: "Laid flat and plucked with picks in set patterns 閑掻 shizugaki and 早掻 hayagaki.",
  skills: "Patterned arpeggios marking the beat cycle, without pressing the strings.",
  scenes: "Imperial court gagaku, Heian aristocratic music-making, shrine and temple ceremonies.",
  partners: ["gakubiwa","sho","ryuteki"],
  sound: "A soft, plain, slightly dry pluck that rings briefly; its fixed arpeggio patterns sound as gentle rippling markers under the wind melody.",
  tuning: "Thirteen strings tuned to the gagaku mode of each piece, such as 平調 hyōjō or 壱越調 ichikotsuchō, mostly pentatonic with octave doublings.",
  acoustics: "Plucked with small bamboo picks on the thumb, index and middle fingers; strings over movable bridges drive the paulownia soundboard.",
  making: "Made by specialist instrument makers from paulownia, much like the later koto but with silk strings and smaller picks.",
  role: "Rhythmic-harmonic accompaniment: it plays fixed patterns 閑掻 shizugaki and 早掻 hayagaki that mark the phrases.",
  players: "Musicians of the Imperial Household Agency music department and earlier court nobles; the Tale of Genji depicts aristocrats playing it.",
  repertoire: "管絃 kangen pieces such as 越天楽 Etenraku and 五常楽.",
  notation: "Tablature naming the strings and patterns in vertical columns, in gagaku part-books.",
  finds: "Heian texts and paintings show it at court; the Nara-period Shōsōin holds related zithers.",
  today: "Living in imperial and other gagaku ensembles; gagaku is on UNESCO's Representative List (2009).",
  hs: "312.22-5",
  relatives: ["koto","guzheng","wagon","se"],
  techniques: [
    { name: "Stroke patterns", native: "閑掻・早掻", how: "Set patterns of two or three plucked strings punctuate the gagaku melody.", play: "normal" },
    { name: "Sweep", how: "Several strings are swept in one gesture, a soft arpeggio.", play: "gliss" },
  ],
