  origin: "A narrative lute of the 薩摩 Satsuma domain in southern Kyushu, developed by the 16th century from the biwa of blind priests 盲僧.",
  history: "Promoted by the Shimazu clan to build samurai spirit, it sang war tales in the Edo period and spread across Japan in the Meiji era.",
  materials: "A mulberry body, four or five strings, tall frets, a very large wide bachi plectrum.",
  usage: "Held upright on the lap; the singer strums and strikes the body with the bachi between sung phrases.",
  skills: "Pressing behind high frets to bend pitch, percussive bachi strikes on the body, sweeping rolls.",
  scenes: "Samurai education and war-tale recitation such as the 平家物語 and 城山.",
  partners: ["shakuhachi","shamisen","dadaiko"],
  sound: "A powerful, percussive twang with buzzing high frets; the huge plectrum snaps against the body for sharp strikes and sweeps through the strings in dramatic flourishes between sung lines.",
  tuning: "Four or five strings tuned in fourths and fifths to suit the singer's voice; the high frets let the player bend notes by pressing.",
  acoustics: "A large plectrum strikes the strings and the body; the strings buzz on tall frets and drive the mulberry belly.",
  making: "Carved by specialist makers from hard mulberry 桑, with a large wooden or boxwood plectrum.",
  role: "Solo self-accompaniment to sung narrative, giving interludes and dramatic punctuation.",
  players: "Originally samurai of the Satsuma domain; later professional reciters, men and women, of the 錦心流 and 鶴田流 schools.",
  repertoire: "Narratives of war and loyalty such as 城山, 平家物語 episodes and 敦盛; 鶴田錦史 played it in Takemitsu's November Steps (1967).",
  notation: "Learned mostly by ear from a teacher; schools use written texts with marks for melodic patterns.",
  variants: "Four-string and five-string forms; the 筑前琵琶 Chikuzen biwa is a gentler relative from northern Kyushu.",
  today: "Living, with a small number of professional and amateur players.",
