  skills: "さわり sawari buzzing resonance, スリ slides, ハジキ left-hand plucks, 打ち hammering, Tsugaru-style fast strikes.",
  scenes: "Kabuki and bunraku, 長唄 and 地歌, geisha entertainment, folk songs.",
  partners: ["koto","shakuhachi","kokyu"],
  sound: "A dry, buzzing twang with a percussive snap as the plectrum strikes both string and skin; the 'sawari' buzz on the lowest string gives a sitar-like sustained shimmer. Thin-necked types sound light and bright, the thick-necked Tsugaru style hard, driving and percussive.",
  range: "About three octaves; the open strings are pitched to suit the singer.",
  tuning: "Three strings in moveable tunings: 本調子 honchōshi (fourth + fifth), 二上り niagari (fifth + fourth) and 三下り sansagari (fourth + fourth), with no fixed absolute pitch.",
  acoustics: "A plectrum strikes the silk strings and the skin membrane; the skin-covered box resonates, and the bottom string touches a ridge 'sawari' to buzz.",
  making: "Made by professional shamisen makers: the body of Chinese quince or red sandalwood, neck of rosewood in three detachable parts, the skin stretched very tightly by hand.",
  role: "Melody and accompaniment to song, narrative and dance; solo in Tsugaru style.",
  players: "Blind professional musicians, kabuki and bunraku players, geisha, and folk singers; the Tsugaru style grew from itinerant blind 坊様 bosama players.",
  repertoire: "長唄 nagauta, 義太夫節 gidayū in bunraku, 地歌, 小唄, 端唄 and 津軽じょんがら節.",
  notation: "Number tablature 文化譜 bunkafu and other school notations giving finger positions on the neck.",
  finds: "Tradition holds that the sanshin arrived through the port of 堺 Sakai in the Eiroku era (1558–1570).",
  variants: "細棹 hosozao (thin neck), 中棹 chūzao and 太棹 futozao (thick neck), each matched to a genre.",
  today: "Living; kabuki and bunraku, which it accompanies, are on UNESCO's Representative List (2008).",
