  origin: "The transverse flute of 能 noh theatre, developed in the 14th century from the ryūteki.",
  history: "A narrow tube 喉 nodo inserted inside makes its overblown octaves deliberately out of tune, giving the piercing 'hishigi' cry; it is also used in kabuki.",
  materials: "Smoked bamboo split and reassembled inside out, bound with cherry bark and lacquered, seven finger holes, an inner nodo tube.",
  usage: "Held horizontally; played by one musician in the noh 囃子 hayashi ensemble.",
  skills: "The ヒシギ hishigi shriek, 指打ち finger ornaments, set melodic patterns 唱歌 shōga.",
