  role: "Melodic and atmospheric part in the noh 囃子 hayashi with three drums.",
  players: "Professional noh flutists of hereditary schools such as 一噌流 Isso, 森田流 Morita and 藤田流 Fujita.",
  repertoire: "Noh plays and their dances such as 中之舞 and 神舞; kabuki offstage music.",
  notation: "Learned by singing 唱歌 shōga syllables (ヲヒャーラー…), written in school part-books.",
