  role: "Harmony and sustained cluster background.",
  players: "Court and shrine gagaku musicians; today also contemporary music performers such as 宮田まゆみ Miyata Mayumi.",
  repertoire: "All 唐楽 tōgaku kangen pieces such as 越天楽; its solo prelude 調子 chōshi; many contemporary works.",
  notation: "Gagaku part-books naming the aitake clusters by the pipe names.",
  meaning: "Its sound is said to be the light of heaven, and its shape is likened to a phoenix with folded wings.",
