  origin: "The straight-necked five-string lute of Silla, one of the three string instruments 삼현 of Unified Silla.",
  history: "Distinct from the crook-necked 당비파 dangbipa, it was used in native 향악 hyangak music through the Joseon period and disappeared, being revived in recent decades.",
  materials: "A wooden pear-shaped body, a straight neck with frets, five silk strings, a plectrum.",
