  origin: "The Korean hammered dulcimer, introduced from Europe via Qing China in the 18th century, hence 'western zither' 洋琴.",
  history: "It became part of Joseon chamber music 줄풍류 and the 영산회상 suite in the late Joseon.",
  materials: "A trapezoid wooden box, metal strings in courses over two bridges, a thin bamboo stick.",
  usage: "Laid flat and struck with one bamboo stick.",
  skills: "Delicate striking that doubles the melody, light ornaments.",
  scenes: "Joseon salon chamber music 풍류방, 가곡 lyric song accompaniment.",
  partners: ["geomungo","gayageum","haegeum"],
  sound: "Thin, bright, metallic and tinkling, each stroke ringing on with a light shimmer. It is struck with a single slender bamboo stick, so it plays clear single notes rather than rolled tremolos.",
  range: "About two octaves.",
  tuning: "Courses of four metal strings over two bridges give a set of pitches that are tuned for the pentatonic modes of Korean chamber music.",
  acoustics: "Strike: a thin bamboo stick hits courses of metal strings → strings vibrate on either side of the bridges → the trapezoid wooden box resonates.",
  role: "Melody and ornament in chamber ensembles, doubling the string line with a bright sparkle.",
  players: "Court musicians and the amateur musicians of the late Joseon 풍류방 pungnyubang salons.",
  repertoire: "영산회상 Yeongsan hoesang, 천년만세 Cheonnyeon manse, and accompaniment of 가곡 gagok.",
  notation: "An early 19th-century tablature for it, 歐邏鐵絲琴字譜, records its pieces.",
  variants: "One standard form; modern models may have more courses.",
  today: "Living in court and chamber music.",
  hs: "314.122-4",
  relatives: ["santoor","santur"],
  techniques: [
    { name: "Struck note", how: "A thin bamboo stick strikes the wire courses, a bright, ringing tone.", play: "normal" },
  ],
