  origin: "A Korean bowed zither, from the Chinese yazheng brought in the Goryeo period.",
  history: "The court ajaeng with seven strings is rubbed with a resined forsythia stick; a smaller 산조 아쟁 with a horsehair bow was developed in the 20th century for sanjo and folk music.",
  materials: "A paulownia body, seven to nine thick silk strings, movable bridges, a resined forsythia stick or horsehair bow.",
  usage: "Laid on the floor angled up; the right hand draws the stick across the strings, the left presses beyond the bridges.",
  skills: "Heavy sustained bass lines, deep 농현 vibrato, sobbing bends.",
  scenes: "Court music, shaman ritual music 시나위, sanjo and pansori accompaniment.",
  partners: ["haegeum","daegeum","piri"],
  sound: "Low, rough and rasping, with a gritty, buzzing sustain from the resined stick on thick silk strings; it is the bass of Korean strings. The sanjo ajaeng's horsehair bow gives a smoother, sobbing tone with deep vibrato.",
  range: "The lowest of the Korean strings, about two octaves.",
  tuning: "Movable bridges are set to the pentatonic scale of the piece.",
  acoustics: "Friction: a resined forsythia stick or a horsehair bow rubs thick strings → strings vibrate between bridge and end → the paulownia body resonates.",
  making: "Made by 악기장 craftsmen like the gayageum, with a heavier body and thicker strings.",
  role: "Bass and sustained melody in court ensembles; a soloist in sanjo and an expressive voice in 시나위 sinawi.",
  players: "Court musicians; folk and shaman-ritual musicians for the sanjo ajaeng.",
  repertoire: "수제천 Sujecheon, 영산회상 Yeongsan hoesang, 아쟁 산조 ajaeng sanjo, 시나위 sinawi and 판소리 accompaniment.",
  notation: "정간보 jeongganbo for court music.",
  variants: "The seven-string court ajaeng (정악 아쟁), the eight- or nine-string sanjo ajaeng, and modern larger models.",
  today: "Living.",
  hs: "314.122-71",
  relatives: ["yazheng","gayageum","haegeum"],
