  tuning: "Each pipe's reed and length are fixed to a pitch of the Korean twelve-lü system, tuned with wax on the reed.",
  acoustics: "Breath: blowing or sucking through the wind chest → brass free reeds at the pipe feet vibrate → a pipe sounds only when its finger hole is closed, its air column tuning the reed.",
  making: "Bamboo pipes with brass reeds set into a wind chest, once a gourd 박, now wood or metal.",
  role: "Harmony and ornamented melody; it is the only Korean instrument that plays chords.",
  players: "Court musicians and chamber musicians.",
  repertoire: "The duet 생소병주 with the 단소 danso, especially 수룡음 Suryongeum, and 영산회상 Yeongsan hoesang.",
  notation: "정간보 jeongganbo.",
  finds: "Heavenly musicians on the bronze bell of 상원사 Sangwonsa (725) play the saenghwang and the konghou.",
