  origin: "The horse-head fiddle of the Mongols (Mongolian моринхуур), whose legends tie it to a beloved horse.",
  history: "Bowed lutes spread across the steppe from the 13th century; the trapezoid wooden morin khuur with a carved horse head took its present form in the 19th–20th centuries and is listed by UNESCO as intangible heritage.",
  materials: "A trapezoid wooden sound box (formerly skin-covered), two strings and a bow of horsehair (now often nylon), a carved horse-head scroll.",
  usage: "Held between the knees and bowed; the left hand stops the strings with the fingernails and fingertips from the side.",
  skills: "Imitations of galloping and neighing, overtone-rich double stops, ornaments in 長調 urtyn duu long-song style.",
