  origin: "A fretless lute of North India, developed in the 19th century from the Afghan rubab by Afghan musician families settled in India.",
  history: "Musicians such as the Bangash family and later Allauddin Khan and Ali Akbar Khan of the Maihar gharana (with strong Bengali ties) made it a major classical instrument.",
  materials: "A wooden body covered with goatskin, a polished metal fingerboard, metal playing and sympathetic strings, a coconut-shell plectrum.",
  usage: "Held across the lap, plucked with a plectrum while the fingernails slide on the metal fingerboard.",
  skills: "Long slides 'meend' on the fretless board, gamak, jhala strumming, fast tans.",
  scenes: "Hindustani classical concerts, especially in Bengal and the Maihar tradition.",
  partners: ["pakhawaj","tanpura","sitar"],
