  players: "Hindustani classical musicians, especially of the Maihar and Bangash (Gwalior–Bangash) lineages.",
  repertoire: "Raga performance in alap, jor, jhala and gat; known through Allauddin Khan, Ali Akbar Khan and Amjad Ali Khan.",
  notation: "Taught orally with bols, with sargam or Bhatkhande notation as aids.",
  today: "Living in Hindustani classical music.",
