  origin: "The Persian outdoor shawm (surnā, 'festival pipe'), carried into India by the Delhi Sultanate and Deccan courts.",
  history: "It played in the naubat drum houses and military bands with kettledrums and long trumpets; it is the ancestor of the shehnai, suona and many shawms.",
  materials: "A conical wooden body, a small double reed on a metal staple, a lip disc, a flared bell.",
  usage: "Played loudly outdoors with the lips resting on the disc.",
  skills: "Circular breathing, ornamented fanfares and melodies.",
  scenes: "Naubat ceremonies at palace gates, military marches, weddings and festivals.",
  partners: ["nagara","shehnai","karnay"],
