  origin: "The arched harp of Burma, descended from ancient Indian harps; Pyu and later Bamar courts played it.",
  history: "It is the last living arched harp of an old Indian lineage; the classical repertoire 'Mahagita' was codified at the Konbaung court, and the harp grew from 13 to 16 strings.",
  materials: "A boat-shaped padauk wood body covered with deer hide, a curved acacia-root neck, silk or nylon strings tied with red cords.",
  usage: "Held on the lap with the neck to the left; the right fingers pluck while the left hand stops strings at the neck to raise pitch.",
  skills: "Stopping strings with the left thumb for altered pitches, damping, rippling arpeggios.",
  scenes: "Royal court chamber music, classical song 'Mahagita', modern solo recitals.",
  partners: ["pattala","palwei","hne"],
  sound: "A soft, warm and intimate plucked tone with a slightly buzzy, silken attack and a gentle ringing decay; left-hand stopping gives small bends, and rippling runs sound delicate rather than loud.",
  range: "Sixteen strings, about three octaves.",
  tuning: "Each string is tuned by sliding its cord ring along the neck; the harp is retuned to Burmese modes such as hnyin lone, aung myin and pale.",
