  origin: "The Vietnamese monochord of the Kinh (Việt) people, its single string bent by a flexible rod.",
  history: "First firmly recorded in the 18th century, it was played by blind street singers and became the emblem of Vietnamese music in the 20th century, later with an electric pickup.",
  materials: "A long wooden or bamboo box, one steel string, a buffalo-horn or bamboo flexible rod with a gourd, a thin plectrum.",
  usage: "Laid flat; the right hand plucks harmonics with a pick while touching the string with the palm edge, the left bends the rod.",
  skills: "Playing only harmonics, wide glides and vibrato by bending the rod, voice-like ornaments.",
  scenes: "Folk song, ca trù and chèo theatre, street singing 'hát xẩm', modern solos.",
  partners: ["dan-tranh","sao-truc","dan-nhi"],
  sound: "A pure, flute-like, singing harmonic that the player bends into wide, wailing glides and slow vibrato, like a human voice; amplified versions sustain longer and sound almost like a theremin.",
  range: "About 3 octaves of harmonics, bent further by the rod.",
  tuning: "The single string is usually tuned to C3 or similar; notes come from harmonics at the ½, ⅓, ¼… points, with pitches between reached by bending the rod.",
  acoustics: "Plectrum pluck while the palm touches a node → single steel string (harmonics) → long box resonator; the flexible rod changes tension.",
  making: "Made by specialist luthiers, chiefly around Hà Nội; the box is wooden or bamboo, the rod buffalo horn, and modern ones carry a pickup.",
  role: "Melody: solo voice over plucked and bowed instruments.",
  players: "Formerly blind itinerant singers; now trained conservatory soloists, men and women.",
  repertoire: "Hát xẩm street songs, northern folk songs, 'Vọng cổ' arrangements, modern solos such as 'Tiếng đàn bầu'.",
  meaning: "A Vietnamese saying warns girls not to listen to the đàn bầu, so seductive is its sound.",
  variants: "Bamboo-tube and wooden-box forms; the Jing people of Guangxi play the same instrument (独弦琴).",
  today: "Living and iconic; hát xẩm is being revived.",
  hs: "314.122-5",
  relatives: ["dan-tranh","dan-nhi"],
  uncertain: "Its origin before the 18th century is undocumented, and the Hornbostel–Sachs placement of a monochord with a tension rod varies among authors.",
